WITH base AS (SELECT id, customer_id, device, browser, started_at, CAST(started_at AS DATE) AS started_at_day, COALESCE(browser, 'UNKNOWN') AS resolved_browser FROM sessions WHERE started_at >= TIMESTAMP '2023-08-24 08:00:00' AND customer_id IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM base), sessions_sessions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT CASE WHEN is_new_burst >= 1 THEN 'LARGE' ELSE 'SMALL' END AS is_new_burst_tier, MAX(burst_id) AS max_burst_id, MIN(started_at) AS first_started_at, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, PERCENTILE_APPROX(is_new_burst, ARRAY(0.25, 0.5, 0.75)) AS is_new_burst_quartiles, PERCENTILE_APPROX(burst_id, 0.95) AS burst_id_p95 FROM sessions_sessions GROUP BY CUBE (CASE WHEN is_new_burst >= 1 THEN 'LARGE' ELSE 'SMALL' END);
